import java.util.*;

class Solution {
  public int minTransfers(int[][] transactions) {
    Map<Integer, Integer> balance = new HashMap<>();
    for (int[] t : transactions) {
      balance.merge(t[0], -t[2], Integer::sum);
      balance.merge(t[1], t[2], Integer::sum);
    }
    List<Integer> debts = new ArrayList<>();
    for (int b : balance.values()) if (b != 0) debts.add(b);
    return settle(debts.stream().mapToInt(Integer::intValue).toArray(), 0);
  }

  // settle debt[s] against every later debt of the opposite sign, one transfer each
  private int settle(int[] debt, int s) {
    while (s < debt.length && debt[s] == 0) s++;
    if (s == debt.length) return 0;
    int best = Integer.MAX_VALUE;
    for (int i = s + 1; i < debt.length; i++) {
      if ((long) debt[i] * debt[s] >= 0) continue;
      debt[i] += debt[s];
      best = Math.min(best, 1 + settle(debt, s + 1));
      debt[i] -= debt[s];
    }
    return best;
  }
}
